AIService.bootstrap:
ai::AIGoalDefinition goal; goal.id = ai::AIGoalId::FromString("participant.goal"); goal.canonical_name = "participant.goal"; goal.intent_type = ai::AIIntentTypeId::FromString("participant.intent"); goal.target_policy = ai::AITargetPolicy::Required;
    ai::AIConsideration consideration; consideration.id = ai::AIConsiderationId::FromString("participant.consideration"); consideration.evaluator = ai::AIService::InputEvaluatorId(); consideration.input_key = ai::AIInputKeyId::FromString("participant.score"); consideration.scope = ai::AIConsiderationScope::Target; consideration.weight_micro = ai::kFixedOne; goal.considerations = {consideration};
    participant_tests::Check(bool(owner.RegisterGoal(goal)), "ai fixture goal");
    ai::AIProfile profile; profile.id = ai::AIProfileId::FromString("participant.profile"); profile.canonical_name = "participant.profile"; profile.default_goals = {goal.id}; profile.materialization_policy = ai::AIMaterializationPolicy::AbstractCapable; profile.think_interval = GameplayDuration{1};
    participant_tests::Check(bool(owner.RegisterProfile(profile)), "ai fixture profile");
    const auto profile_id = profile.id;

DialogueService.bootstrap:
dialogue::ConversationDefinition definition; definition.canonical_name = "participant.conversation"; definition.entry_node = dialogue::DialogueNodeId::FromString("participant.node");
    dialogue::DialogueNodeDefinition node; node.id = definition.entry_node;
    dialogue::DialogueOptionDefinition option; option.id = dialogue::DialogueOptionId::FromString("participant.option"); option.next_node = node.id; node.options.push_back(option); definition.nodes.push_back(node);
    auto definition_id = owner.RegisterConversation(definition); participant_tests::Check(bool(definition_id), "dialogue fixture definition");

DialogueService.seed:
const GameplayObjectRef subject{GameplayDomainId::FromString("fixture"), GameplayObjectId::FromString("subject")};
    const GameplayObjectRef peer{GameplayDomainId::FromString("fixture"), GameplayObjectId::FromString("peer")};
    participant_tests::Check(bool(owner.StartConversation(definition_id.Value(), std::vector<GameplayObjectRef>{subject, peer})), "seed actual waiting conversation");

LootService.bootstrap:
class RewardHandler final : public loot::IRewardHandler {
    public:
      loot::RewardTypeId Type() const noexcept override { return loot::RewardTypeId::FromString("participant.reward"); }
      epidemic::foundation::Result<loot::RewardDeliveryStage> Prepare(const loot::RewardOperation& operation) override { return epidemic::foundation::Result<loot::RewardDeliveryStage>::Success({operation, loot::RewardDeliveryDisposition::Delivered}); }
      void Commit(loot::RewardDeliveryStage&) noexcept override {}
      void Cancel(loot::RewardDeliveryStage&) noexcept override {}
    };
    RewardHandler handler; participant_tests::Check(bool(owner.RegisterRewardHandler("participant.reward", &handler)), "loot fixture handler");
    loot::RewardDefinition reward; reward.canonical_name = "participant.gold"; reward.type = handler.Type(); reward.min_quantity_micro = reward.max_quantity_micro = 10;
    auto reward_id = owner.RegisterRewardDefinition(reward); participant_tests::Check(bool(reward_id), "loot fixture reward");
    loot::LootTableDefinition table; table.canonical_name = "participant.table"; table.policy = loot::LootRollPolicy::GuaranteedAll; table.entries.push_back({loot::LootEntryId::FromString("participant.entry"), 1, 1'000'000, reward_id.Value(), {}, {}});
    auto table_id = owner.RegisterLootTable(table); participant_tests::Check(bool(table_id), "loot fixture table");

LootService.seed:
loot::LootContext context; context.recipient = {GameplayDomainId::FromString("fixture"), GameplayObjectId::FromString("subject")}; context.seed = {42};
    auto generated = owner.GenerateTracked(table_id.Value(), context); participant_tests::Check(bool(generated), "seed actual generated loot");
    participant_tests::Check(bool(owner.MakePending(std::move(generated).Value())), "seed actual pending reward");
